using System;using System.Collections.Generic;using System.Threading;using Ashfall.Core;using Ashfall.Modules.HealthStates;using Ashfall.Modules.Presentation;using Ashfall.Integration.PersonalSettings;
static class PresentationR7Tests {
 sealed class Sink:ITargetFeedbackPort {public List<float> Amounts=new List<float>();public void Emit(string target,float amount,bool shield){Amounts.Add(amount);}}
 sealed class Fixture {
  public readonly EnvironmentPorts World=new EnvironmentPorts();public readonly HealthService Health;public readonly HudModel Hud=new HudModel();public readonly Sink Output=new Sink();public readonly TargetFeedbackBinding Binding;long tick;
  public CommandContext C(){return new CommandContext("s","p","r7-"+(++tick),tick,0,true);}
  public Fixture(){Health=new HealthService("s",0,0,true,World,World,World);Check(Health.Register(C(),"p",-1,false).Accepted,"register");Check(Health.Register(C(),"q",-1,false).Accepted,"register q");Health.DrainTransitions();Hud.Update(new HudInput(),false,0);Binding=new TargetFeedbackBinding(Health,"s",0,"p",Hud,Output);}
  public HealthTransition Hit(float amount,string target="p"){var h=Health.Read(target);Check(Health.ApplyLoss(C(),target,h.Revision,amount,0,false).Accepted,"actual hit");var es=Health.DrainTransitions();Check(es.Length==1,"single actual event");return es[0];}
  public HealthTransition Connect(bool connected){var h=Health.Read("p");Check(Health.SetConnected(C(),"p",h.Revision,connected).Accepted,"connect");return Health.DrainTransitions()[0];}
  public HealthTransition Heal(){var h=Health.Read("p");HealthService.PreparedGain token;Check(Health.PrepareGain(C(),"heal","p",h.Revision,h.LifeGeneration,h.ConnectionGeneration,5,0,out token)&&token.Validate(),"prepare actual heal");token.CommitValidated();return Health.DrainTransitions()[0];}
 }
 static int pass,fail;static void Check(bool b,string m){if(!b)throw new Exception(m);}static void Test(string n,Action a){try{a();pass++;Console.WriteLine("PASS "+n);}catch(Exception e){fail++;Console.WriteLine("FAIL "+n+": "+e);}}
 static void Exact(Fixture f,int count,float amount){Check(f.Output.Amounts.Count==count,"count "+f.Output.Amounts.Count);if(count>0)Check(f.Output.Amounts[count-1]==amount,"amount "+f.Output.Amounts[count-1]);}
 public static int Main(){
 Test("foreign7 observed only then local11 observed before authorized emits11 not18",delegate{var f=new Fixture();f.Binding.ObserveTransition(f.Hit(7));Exact(f,0,0);var e=f.Hit(11);f.Binding.ObserveTransition(e);f.Binding.OnAuthorizedOutgoingTransition(e);f.Binding.OnAuthorizedOutgoingTransition(e);f.Binding.ObserveTransition(e);Exact(f,1,11);});
 Test("authorize before observe SAME event once",delegate{var f=new Fixture();var e=f.Hit(11);f.Binding.OnAuthorizedOutgoingTransition(e);f.Binding.ObserveTransition(e);f.Binding.OnAuthorizedOutgoingTransition(e);Exact(f,1,11);});
 Test("delayed predecessor repairs unresolved exact local delta",delegate{var f=new Fixture();var foreign=f.Hit(7);var e=f.Hit(11);f.Binding.OnAuthorizedOutgoingTransition(e);Exact(f,0,0);f.Binding.ObserveTransition(foreign);Exact(f,1,11);});
 Test("missing foreign event explicit exact producer before repairs gap",delegate{var f=new Fixture();f.Hit(7);var before=f.Health.Read("p");var e=f.Hit(11);f.Binding.OnAuthorizedOutgoingTransition(e);Exact(f,0,0);Check(f.Binding.ObserveTransition(e,before),"exact snapshot");Exact(f,1,11);});
 Test("current snapshot cannot repair missing before; no aggregate",delegate{var f=new Fixture();f.Hit(7);var e=f.Hit(11);Check(!f.Binding.ObserveTransition(e,f.Health.Read("p")),"accepted after as before");f.Binding.OnAuthorizedOutgoingTransition(e);Exact(f,0,0);});
 Test("foreign heal observation maintains exact next damage",delegate{var f=new Fixture();f.Binding.ObserveTransition(f.Hit(7));f.Binding.ObserveTransition(f.Heal());var e=f.Hit(11);f.Binding.ObserveTransition(e);f.Binding.OnAuthorizedOutgoingTransition(e);Exact(f,1,11);});
 Test("delayed multi target interleave does not share watermarks",delegate{var f=new Fixture();var q=new Sink();var qb=new TargetFeedbackBinding(f.Health,"s",0,"q",f.Hud,q);var p=f.Hit(11);var e=f.Hit(9,"q");f.Binding.ObserveTransition(e);qb.ObserveTransition(p);qb.ObserveTransition(e);qb.OnAuthorizedOutgoingTransition(e);f.Binding.ObserveTransition(p);f.Binding.OnAuthorizedOutgoingTransition(p);Exact(f,1,11);Check(q.Amounts.Count==1&&q.Amounts[0]==9,"q");});
 Test("reverse target order with late authorization retains individual deltas",delegate{var f=new Fixture();var a=f.Hit(7);var b=f.Hit(11);f.Binding.ObserveTransition(b);f.Binding.ObserveTransition(a);f.Binding.OnAuthorizedOutgoingTransition(b);f.Binding.OnAuthorizedOutgoingTransition(a);Check(f.Output.Amounts.Count==2&&f.Output.Amounts[0]==11&&f.Output.Amounts[1]==7,"deltas/order");});
 Test("hidden observation never resurfaces after late authorization",delegate{var f=new Fixture();f.Hud.Update(new HudInput(),true,0);var e=f.Hit(11);f.Binding.ObserveTransition(e);f.Hud.Update(new HudInput(),false,0);f.Binding.OnAuthorizedOutgoingTransition(e);Exact(f,0,0);f.Binding.OnAuthorizedOutgoingTransition(f.Hit(9));Exact(f,1,9);});
 Test("hidden authorization stays consumed across replay",delegate{var f=new Fixture();var e=f.Hit(11);f.Binding.ObserveTransition(e);f.Hud.Update(new HudInput(),true,0);f.Binding.OnAuthorizedOutgoingTransition(e);f.Hud.Update(new HudInput(),false,0);f.Binding.OnAuthorizedOutgoingTransition(e);Exact(f,0,0);});
 Test("connection mutation observed then new generation hit exact",delegate{var f=new Fixture();var old=f.Hit(7);f.Binding.ObserveTransition(old);f.Binding.ObserveTransition(f.Connect(false));f.Binding.ObserveTransition(f.Connect(true));f.Binding.OnAuthorizedOutgoingTransition(old);Exact(f,0,0);f.Binding.OnAuthorizedOutgoingTransition(f.Hit(11));Exact(f,1,11);});
 Test("life mutation observation enables next life and rejects old delayed damage",delegate{var f=new Fixture();var old=f.Hit(7);f.Binding.ObserveTransition(old);f.Binding.ObserveTransition(f.Hit(100));f.World.Now=6;var h=f.Health.Read("p");Check(f.Health.Spawn(f.C(),"p",h.Revision,100,100).Accepted,"actual host spawn");foreach(var e in f.Health.DrainTransitions())f.Binding.ObserveTransition(e);f.World.Now=10;f.Binding.OnAuthorizedOutgoingTransition(old);Exact(f,0,0);f.Binding.OnAuthorizedOutgoingTransition(f.Hit(11));Exact(f,1,11);});
 Test("other session and epoch receipt rejected",delegate{var f=new Fixture();var other=new HealthService("other",0,0,true,f.World,f.World,f.World);Check(other.Register(new CommandContext("other","p","r",1,0,true),"p",-1,false).Accepted,"other register");Check(!f.Binding.ObserveTransition(other.DrainTransitions()[0]),"foreign session");var wrong=new TargetFeedbackBinding(f.Health,"s",1,"p",f.Hud,f.Output);Check(!wrong.ObserveTransition(f.Hit(11)),"foreign epoch");Exact(f,0,0);});
 Test("host thread binding rejects worker callbacks",delegate{var f=new Fixture();var e=f.Hit(11);bool rejected=false;var t=new Thread(delegate(){try{f.Binding.OnAuthorizedOutgoingTransition(e);}catch(InvalidOperationException){rejected=true;}});t.Start();t.Join();Check(rejected,"worker accepted");f.Binding.OnAuthorizedOutgoingTransition(e);Exact(f,1,11);});
 Test("bounded retirement prevents replay after history saturation",delegate{var f=new Fixture();var first=f.Hit(.01f);f.Binding.OnAuthorizedOutgoingTransition(first);for(int i=0;i<TargetFeedbackBinding.HistoryCapacity+3;i++)f.Binding.ObserveTransition(f.Hit(.01f));f.Binding.OnAuthorizedOutgoingTransition(first);Exact(f,1,f.Output.Amounts[0]);});
 Console.WriteLine("TOTAL "+pass+" PASS "+fail+" FAIL");return fail==0?0:1;
 }
}
